"""Build only phase18 documentary outputs."""
from pathlib import Path
import json,hashlib,importlib.util
D=Path('docs/coach/phase18')
spec=importlib.util.spec_from_file_location('phase17_formatter','tools/passive-qualification/build.py');fmt=importlib.util.module_from_spec(spec);spec.loader.exec_module(fmt)
def main():
 files=[('anatomical-uncertainties.md','1 · Les 57 questions anatomiques'),('c3d-integrity-and-timing.md','2 · C3D : erratum et synchronisation'),('independent-review-dossier.md','3 · Dossier de revue indépendante'),('expert-questionnaire.md','4 · Questionnaire et fiche de retour'),('animation-admission-criteria.md','5 · Critères pour une future expérimentation'),('historical-report-differences.md','6 · Comprendre les rapports historiques'),('decision-report.md','7 · Décision et prochaines étapes')]
 s='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PARISFIT · Phase18 · Expertise indépendante</title><style>*{box-sizing:border-box}body{margin:0;background:#edf5ef;color:#173f33;font:16px/1.65 system-ui;overflow-wrap:anywhere}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:clamp(30px,5vw,48px);line-height:1.15}h2,h3{line-height:1.3}section,details{background:white;border-radius:16px;padding:24px;margin:22px 0;min-width:0}summary{font-weight:700;cursor:pointer}a{color:#176e50}.tag{display:inline-block;border-radius:24px;background:#f7d5c8;padding:8px 18px}.notice{border-left:4px solid #df775e;padding-left:18px}table{border-collapse:collapse;min-width:650px;font-size:14px;width:100%}.table-wrap{overflow-x:auto;max-width:100%}th,td{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid #d9e7dd}code{font-size:.9em}pre{white-space:pre-wrap}img{max-width:100%;height:auto}footer{padding:30px 0}</style><main><a href="../phase17/index.html">← Phase17 : preuves originales</a><p>PARISFIT / COACH / PHASE18</p><h1>Préparer la contradiction.<br>Ne pas présumer la validation.</h1><p class="tag">B — Dossier encore incomplet</p><p>AB01 · Squat / 1 · Static / 1. Aucun expert contacté, aucun avis obtenu.</p><section><h2>Deux incertitudes techniques mieux expliquées</h2><p class="notice"><b>Erratum C3D :</b> l’en-tête brut indique 0–2947 pour 2948 frames. Le compte des octets concorde. Le dépassement provient de la propriété calculée du lecteur, que le rapport phase17 avait appelée à tort «headerLastFrame». Aucun fichier réparé ; aucune perte physique de frame démontrée.</p><p><b>Rapports de transition :</b> une collision d’identifiants de clips dans l’ancien laboratoire explique le doublon. Une garde existait déjà depuis la phase4. Ce changement de contexte de mesure n’est pas une amélioration biomécanique du mouvement.</p></section><section><h2>Ce qui reste à examiner par un expert</h2><p>57 marqueurs, 44 définitions documentaires confirmées et 13 plausibles inchangées. Centres articulaires, tissus mous, latéralité, scaling individuel, forces et limites du transfert restent à qualifier.</p><p>Pièces manquantes : dépendances modifiées exactes, logs individuels AB01, preuves de placement et de synchronisation, indices officiels des phases. Le dossier est utile pour un avis préliminaire, pas présenté comme complet.</p><p><a href="../phase17/markerset-schematic.svg">Schéma documentaire des 57 marqueurs</a> · <a href="../phase17/marker-anatomical-mapping.csv">Table source 44 / 13</a> · <a href="../phase17/source-manifest.json">Manifest et empreintes</a></p><img src="../phase17/static-marker-projections.svg" alt="Points mesurés de la première frame statique, sans squelette reconstruit"></section><h2>Les sept livrables</h2>'''
 for name,title in files:s+='<details><summary>'+title+'</summary><p><a href="'+name+'">Ouvrir le fichier Markdown</a></p>'+fmt.md((D/name).read_text())+'</details>'
 s+='<section><h2>Preuves et reproduction</h2><ul>'
 for n in ['marker-review-register.csv','marker-review-register.json','expert-feedback-template.json','c3d-independent-byte-audit.json','python-c3d-reader-evidence.txt','historical-diff.json','historical-code-evidence.txt','historical-mobile-code-evidence.txt','cache-identity.json','REPRODUCE.md','test-results.md','protected-baseline.json','review-status.json','browser-report.json','manifest.json']:s+='<li><a href="'+n+'">'+n+'</a></li>'
 s+='</ul></section><footer>PR11 en brouillon. Aucun scaling, IK, retargeting, correction ou nouvelle animation. Rocketbox, runtime et huit exercices préservés. Aucun envoi, achat, fusion ni déploiement. PASS technique ≠ validation anatomique.</footer></main></html>'
